package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DatabindContext;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class ClassNameIdResolver__typeFromId_TriageGen2Test {

    private TypeFactory typeFactory;
    private DatabindContext databindContext;
    private DeserializationContext deserializationContext;
    private JavaType baseType;
    private ClassNameIdResolver resolver;

    // Test subclass to expose protected method
    private static class TestableClassNameIdResolver extends ClassNameIdResolver {
        public TestableClassNameIdResolver(JavaType baseType, TypeFactory typeFactory) {
            super(baseType, typeFactory);
        }

        @Override
        public JavaType typeFromId(DatabindContext ctxt, String id) throws IOException {
            return _typeFromId(id, ctxt);
        }
    }

    @Before
    public void setup() {
        typeFactory = mock(TypeFactory.class);
        databindContext = mock(DatabindContext.class);
        deserializationContext = mock(DeserializationContext.class);
        baseType = mock(JavaType.class);

        when(databindContext.getTypeFactory()).thenReturn(typeFactory);
        // For the branch where ctxt is DeserializationContext
        when(databindContext.getTypeFactory()).thenReturn(typeFactory);

        resolver = new TestableClassNameIdResolver(baseType, typeFactory);
    }

    @Test
    public void testTypeFromId_WithGenerics() throws IOException {
        String idWithGenerics = "java.util.List<java.lang.String>";
        JavaType expectedType = mock(JavaType.class);

        when(typeFactory.constructFromCanonical(idWithGenerics)).thenReturn(expectedType);

        JavaType result = resolver.typeFromId(databindContext, idWithGenerics);

        assertEquals(expectedType, result);
        verify(typeFactory).constructFromCanonical(idWithGenerics);
        verify(typeFactory, never()).findClass(anyString());
    }

    @Test
    public void testTypeFromId_SimpleClassFound() throws IOException {
        String id = "java.lang.String";
        Class<String> cls = String.class;
        JavaType expectedType = mock(JavaType.class);

        when(typeFactory.findClass(id)).thenReturn(cls);
        when(typeFactory.constructSpecializedType(baseType, cls)).thenReturn(expectedType);

        JavaType result = resolver.typeFromId(databindContext, id);

        assertEquals(expectedType, result);
        verify(typeFactory).findClass(id);
        verify(typeFactory).constructSpecializedType(baseType, cls);
    }

    @Test
    public void testTypeFromId_ClassNotFound_WithDeserializationContext() throws IOException {
        String id = "UnknownClass";
        JavaType expectedType = mock(JavaType.class);

        // Use the deserialization context mock
        when(databindContext.getTypeFactory()).thenReturn(typeFactory);
        // Since we need to test the 'instanceof DeserializationContext' branch
        // We simulate the context being a DeserializationContext
        DeserializationContext dctxt = mock(DeserializationContext.class);
        when(dctxt.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.findClass(id)).thenThrow(new ClassNotFoundException());
        when(dctxt.handleUnknownTypeId(eq(baseType), eq(id), eq(resolver), anyString())).thenReturn(expectedType);

        // We use the dctxt instead of databindContext
        TestableClassNameIdResolver resolverWithDctxt = new TestableClassNameIdResolver(baseType, typeFactory);

        // To make 'instanceof' work, we must use the actual mock object which is an instance of DeserializationContext
        JavaType result = resolverWithDctxt.typeFromId(dctxt, id);

        assertEquals(expectedType, result);
        verify(dctxt).handleUnknownTypeId(eq(baseType), eq(id), eq(resolverWithDctxt), contains("no such class found"));
    }

    @Test
    public void testTypeFromId_ClassNotFound_WithRegularDatabindContext() throws IOException {
        String id = "UnknownClass";

        when(typeFactory.findClass(id)).thenThrow(new ClassNotFoundException());

        // databindContext is NOT an instance of DeserializationContext here
        JavaType result = resolver.typeFromId(databindContext, id);

        assertNull(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTypeFromId_GenericException() throws IOException {
        String id = "InvalidId";

        when(typeFactory.findClass(id)).thenThrow(new RuntimeException("Some unexpected error"));

        resolver.typeFromId(databindContext, id);
    }

    @Test
    public void testTypeFromId_GenericsEdgeCase_NoAngleBracketsAtStart() throws IOException {
        // The condition is id.indexOf('<') > 0
        // If id is "<String", indexOf is 0, it goes to findClass
        String id = "<String"; 
        Class<?> cls = Object.class;
        JavaType expectedType = mock(JavaType.class);

        when(typeFactory.findClass(id)).thenReturn(cls);
        when(typeFactory.constructSpecializedType(baseType, cls)).thenReturn(expectedType);

        JavaType result = resolver.typeFromId(databindContext, id);

        assertEquals(expectedType, result);
    }
}
